#include <iostream>

// Worker 2: Performs primitive validation
bool isValidRadius(double r) {
    return r >= 0.0;
}

// Worker 1: Acts as a worker to main(), but as a boss to isValidRadius()
double computeCircleArea(double radius) {
    if (!isValidRadius(radius)) {
        return -1.0; // Indicate invalid domain
    }
    constexpr double pi = 3.141592653589793;
    return pi * radius * radius;
}

int main() {
    // main acts as the ultimate Boss function
    double r1 = 5.0;
    double r2 = -2.0;

    std::cout << "Area 1: " << computeCircleArea(r1) << "\n";
    std::cout << "Area 2: " << computeCircleArea(r2) << "\n";

    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    std::cout << std::fixed << std::setprecision(2);

    // Evaluating expressions as arguments
    double c1 = 13.0, d = 3.0, f = 4.0;
    double root = std::sqrt(c1 + d * f); // sqrt(25.0) -> 5.00
    std::cout << "sqrt(13.0 + 3.0 * 4.0) = " << root << "\n";

    // cbrt
    std::cout << "cbrt(27.0) = " << std::cbrt(27.0) << "\n";
    std::cout << "cbrt(-8.0) = " << std::cbrt(-8.0) << "\n";

    // pow and exp/log
    std::cout << "pow(2.0, 7.0) = " << std::pow(2.0, 7.0) << "\n";
    std::cout << "log10(100.0) = " << std::log10(100.0) << "\n";

    // fabs, ceil, floor with negative values
    double neg = -9.8;
    std::cout << "fabs(-9.8) = " << std::fabs(neg) << "\n";
    std::cout << "ceil(-9.8) = " << std::ceil(neg) << "\n";
    std::cout << "floor(-9.8) = " << std::floor(neg) << "\n";

    return 0;
}
